"""PIPELINE STARTING LINE — fixed and verified 2026-10-17.

A lazy UNIX-style generator pipeline in pure Python stdlib.
Five techniques: Pipe (| composition), Validated descriptors,
match/case state machine, self-registering SinkPlugin, autovivified Tree.

FIX APPLIED: export_as() takes fmt as KEYWORD ONLY.
  export_as(fmt="json")     # correct
  export_as("json")         # TypeError — "json" binds to tree_data via partial

Run:  python3 pipeline_starting_line.py
"""

from collections import defaultdict
from dataclasses import dataclass
from functools import partial
import json

class Pipe:
    def __init__(self, func):
        self.func = func
    def __or__(self, other):
        return Pipe(lambda x: other.func(self.func(x)))
    def __ror__(self, other):
        return self.func(other)
    def __call__(self, *args, **kwargs):
        return Pipe(partial(self.func, *args, **kwargs))

class Validated:
    def __init__(self, *validators):
        self.validators = validators
    def __set_name__(self, owner, name):
        self.name = name
    def __set__(self, instance, value):
        for validate in self.validators:
            value = validate(self.name, value)
        instance.__dict__[self.name] = value

def clean_str(name, val):
    if not isinstance(val, str) or not val.strip():
        raise ValueError(f"'{name}' must be a non-empty string")
    return val.strip().lower()

def positive_num(name, val):
    if not isinstance(val, (int, float)) or val <= 0:
        raise ValueError(f"'{name}' must be > 0 (got {val})")
    return float(val)

class PurchaseEvent:
    user = Validated(clean_str)
    category = Validated(clean_str)
    amount = Validated(positive_num)
    def __init__(self, user, category, amount):
        self.user = user
        self.category = category
        self.amount = amount

@dataclass
class RefundEvent:
    user: str

@dataclass
class StandardTier:
    spent: float = 0.0

@dataclass
class VIPTier:
    spent: float
    perks_unlocked: bool = True

def next_loyalty_state(state, event):
    match (state, event):
        case (StandardTier(spent), PurchaseEvent(amount=amt)) if spent + amt >= 500:
            return VIPTier(spent=spent + amt)
        case (StandardTier(spent), PurchaseEvent(amount=amt)):
            return StandardTier(spent=spent + amt)
        case (VIPTier(spent), PurchaseEvent(amount=amt)):
            return VIPTier(spent=spent + amt)
        case (_, RefundEvent()):
            return StandardTier(spent=0.0)
        case _:
            return state

class SinkPlugin:
    _registry = {}
    def __init_subclass__(cls, format_name=None, **kwargs):
        super().__init_subclass__(**kwargs)
        if format_name:
            cls._registry[format_name] = cls
    @classmethod
    def render(cls, format_name, tree_data):
        if format_name not in cls._registry:
            raise ValueError(f"Unknown plugin '{format_name}'. Available: {list(cls._registry)}")
        return cls._registry[format_name]().export(tree_data)

class JSONSink(SinkPlugin, format_name="json"):
    def export(self, data):
        return json.dumps(data, indent=2)

class SummarySink(SinkPlugin, format_name="summary"):
    def export(self, data):
        lines = ["=== EXECUTIVE PIPELINE SUMMARY ==="]
        for user, profile in data["users"].items():
            lines.append(f"• {user.upper()} [{profile['tier']}] -> Total: ${profile['total_spent']:.2f}")
        return "\n".join(lines)

Tree = lambda: defaultdict(Tree)

@Pipe
def parse_events(raw_stream):
    for payload in raw_stream:
        match payload:
            case {"type": "buy", "user": u, "item": {"cat": c, "price": p}}:
                try:
                    yield PurchaseEvent(user=u, category=c, amount=p)
                except ValueError as e:
                    print(f"[Dropped Invalid Record] {e}")
            case {"type": "refund", "user": str(u)}:
                yield RefundEvent(user=u.strip().lower())
            case _:
                print(f"[Ignored Unknown Schema] {payload}")

@Pipe
def run_state_and_aggregate(event_stream):
    report = Tree()
    user_states = defaultdict(StandardTier)
    for event in event_stream:
        user = event.user
        state = user_states[user] = next_loyalty_state(user_states[user], event)
        if isinstance(event, PurchaseEvent):
            cat_node = report["users"][user]["categories"]
            cat_node[event.category] = cat_node.get(event.category, 0.0) + event.amount
        report["users"][user]["tier"] = type(state).__name__
        report["users"][user]["total_spent"] = state.spent
    return report

@Pipe
def export_as(tree_data, fmt="json"):
    return SinkPlugin.render(fmt, tree_data)

if __name__ == "__main__":
    raw_webhooks = [
        {"type": "buy", "user": "  Alice ", "item": {"cat": "Electronics", "price": 300}},
        {"type": "buy", "user": "alice", "item": {"cat": "Books", "price": 250}},
        {"type": "buy", "user": "Bob", "item": {"cat": "Audio", "price": -50}},
        {"type": "buy", "user": "Bob", "item": {"cat": "Audio", "price": 120}},
        {"type": "refund", "user": "Bob"},
        {"type": "buy", "user": "Bob", "item": {"cat": "Gaming", "price": 80}},
        {"type": "ping", "timestamp": 123456789},
    ]
    result_json = (
        raw_webhooks
        | parse_events()
        | run_state_and_aggregate()
        | export_as(fmt="json")
    )
    print("\n--- JSON PLUGIN OUTPUT ---")
    print(result_json)

    print("\n--- SUMMARY PLUGIN OUTPUT ---")
    print(
        raw_webhooks
        | parse_events()
        | run_state_and_aggregate()
        | export_as(fmt="summary")
    )

"""PIPELINE STARTING LINE v2 — fixed, verified, and creatively improved 2026-10-17.

A lazy UNIX-style generator pipeline in pure Python stdlib.

FIX (v1 bug): export_as() takes fmt as KEYWORD ONLY.
  export_as(fmt="json")     # correct
  export_as("json")         # TypeError — "json" binds to tree_data via partial

CREATIVE IMPROVEMENTS (v2):
  1. QUARANTINE — invalid records go to a dead-letter branch (payload +
     reason + timestamp) instead of dying in a print(). Refuse and RECORD.
  2. INSPECTABLE PLAN — every Pipe carries its steps; print() shows the DAG:
     input → parse_events → meter(parse) → ... Never guess the plan again.
  3. STAGE METERS — each stage counts records in/out and times itself.
     Measure what is left over after every interaction.
  4. TEE — fan-out without disturbing the main flow. The demo taps parsed
     events into a VIP-watch branch that reuses the pure state machine.

Run:  python3 pipeline_starting_line.py
"""
from collections import defaultdict
from collections.abc import Iterator
from dataclasses import dataclass
from functools import partial
import inspect
import json
import time

# Shared instruments (populated as the pipeline runs)
METERS = {}       # stage label -> {"records": n, "seconds": t}
QUARANTINE = []   # refused records: {"payload", "reason", "stage", "t"}


# =====================================================================
# 1. THE PIPE ENGINE: composable, inspectable, metered
# =====================================================================
class Pipe:
    """A pipeline stage. `|` composes; print() shows the plan."""
    def __init__(self, func, name=None, steps=()):
        self.func = func
        self.name = name or getattr(func, "__name__", "stage")
        self.steps = steps or (self.name,)

    def __or__(self, other):
        def composed(x):
            return other.func(self.func(x))
        return Pipe(composed, name="composed", steps=self.steps + other.steps)

    def __ror__(self, other):
        return BoundPipe(self.func(other), self.steps)

    def __call__(self, *args, **kwargs):
        tag = ",".join([repr(a) for a in args] +
                       [f"{k}={v!r}" for k, v in kwargs.items()])
        label = f"{self.name}({tag[:24] + '…' if len(tag) > 25 else tag})"
        p = Pipe(partial(self.func, *args, **kwargs), name=label)
        p.steps = self.steps[:-1] + (label,)
        return p

    def __repr__(self):
        return " → ".join(self.steps)


class BoundPipe:
    """A pipeline bound to data. Still inspectable; .unwrap() to finish."""
    def __init__(self, value, steps, _bound=False):
        self.value = value
        self.steps = tuple(steps) if _bound else ("input",) + tuple(steps)

    def __or__(self, pipe):
        return BoundPipe(pipe.func(self.value), self.steps + pipe.steps,
                         _bound=True)

    def __repr__(self):
        return " → ".join(self.steps)

    def unwrap(self):
        return self.value


# =====================================================================
# 2. THE DESCRIPTOR PROTOCOL: Reusable Attribute Validation (__set__)
# =====================================================================
class Validated:
    def __init__(self, *validators):
        self.validators = validators

    def __set_name__(self, owner, name):
        self.name = name

    def __set__(self, instance, value):
        for validate in self.validators:
            value = validate(self.name, value)
        instance.__dict__[self.name] = value


def clean_str(name, val):
    if not isinstance(val, str) or not val.strip():
        raise ValueError(f"'{name}' must be a non-empty string")
    return val.strip().lower()


def positive_num(name, val):
    if not isinstance(val, (int, float)) or val <= 0:
        raise ValueError(f"'{name}' must be > 0 (got {val})")
    return float(val)


# =====================================================================
# 3. DOMAIN MODELS & STATE MACHINE: Dataclasses + Tuple Match/Case
# =====================================================================
class PurchaseEvent:
    user = Validated(clean_str)
    category = Validated(clean_str)
    amount = Validated(positive_num)

    def __init__(self, user, category, amount):
        self.user = user
        self.category = category
        self.amount = amount


@dataclass
class RefundEvent:
    user: str


@dataclass
class StandardTier:
    spent: float = 0.0


@dataclass
class VIPTier:
    spent: float
    perks_unlocked: bool = True


def next_loyalty_state(state, event):
    """Pure (state, event) tuple state machine."""
    match (state, event):
        case (StandardTier(spent), PurchaseEvent(amount=amt)) if spent + amt >= 500:
            return VIPTier(spent=spent + amt)
        case (StandardTier(spent), PurchaseEvent(amount=amt)):
            return StandardTier(spent=spent + amt)
        case (VIPTier(spent), PurchaseEvent(amount=amt)):
            return VIPTier(spent=spent + amt)
        case (_, RefundEvent()):
            return StandardTier(spent=0.0)
        case _:
            return state


# =====================================================================
# 4. PLUGIN ARCHITECTURE: Self-Registering Exporters (__init_subclass__)
# =====================================================================
class SinkPlugin:
    _registry = {}

    def __init_subclass__(cls, format_name=None, **kwargs):
        super().__init_subclass__(**kwargs)
        if format_name:
            cls._registry[format_name] = cls

    @classmethod
    def render(cls, format_name, tree_data):
        if format_name not in cls._registry:
            raise ValueError(
                f"Unknown plugin '{format_name}'. Available: {list(cls._registry)}")
        return cls._registry[format_name]().export(tree_data)


class JSONSink(SinkPlugin, format_name="json"):
    def export(self, data):
        return json.dumps(data, indent=2)


class SummarySink(SinkPlugin, format_name="summary"):
    def export(self, data):
        lines = ["=== EXECUTIVE PIPELINE SUMMARY ==="]
        for user, profile in data["users"].items():
            lines.append(
                f"• {user.upper()} [{profile['tier']}] -> Total: ${profile['total_spent']:.2f}")
        return "\n".join(lines)


class QuarantineSink(SinkPlugin, format_name="quarantine"):
    """Renders the dead-letter branch: every refused record, with reason."""
    def export(self, data):
        lines = ["=== QUARANTINE — REFUSED RECORDS ==="]
        for q in QUARANTINE:
            lines.append(f"• [{q['stage']}] {q['reason']} :: {q['payload']}")
        lines.append(f"Total refused: {len(QUARANTINE)}")
        return "\n".join(lines)


class AlertSink(SinkPlugin, format_name="alerts"):
    def export(self, data):
        lines = ["=== VIP UPGRADE ALERTS ==="]
        for a in data:
            lines.append(f"• {a['user'].upper()} upgraded to VIP at ${a['spent']:.2f}")
        if len(lines) == 1:
            lines.append("(none)")
        return "\n".join(lines)


# =====================================================================
# 5. PIPELINE STAGES
# =====================================================================
Tree = lambda: defaultdict(Tree)  # the 1-line recursive defaultdict


def _refuse(payload, reason, stage):
    """★ Refuse — and record the refusal."""
    QUARANTINE.append({"payload": payload, "reason": reason,
                       "stage": stage, "t": time.time()})


@Pipe
def parse_events(raw_stream):
    """Destructure messy dicts into typed events; refuse the rest."""
    QUARANTINE.clear()  # fresh dead-letter branch per run
    for payload in raw_stream:
        match payload:
            case {"type": "buy", "user": u, "item": {"cat": c, "price": p}}:
                try:
                    yield PurchaseEvent(user=u, category=c, amount=p)
                except ValueError as e:
                    _refuse(payload, str(e), "parse_events")
            case {"type": "refund", "user": str(u)}:
                yield RefundEvent(user=u.strip().lower())
            case _:
                _refuse(payload, "unknown schema", "parse_events")


@Pipe
def meter(stream, label="stage"):
    """★ instrument: count what passes through, time it."""
    t0 = time.perf_counter()
    if inspect.isgenerator(stream) or isinstance(stream, Iterator):
        def _gen():
            n = 0
            for item in stream:
                n += 1
                yield item
            METERS[label] = {"records": n,
                             "seconds": round(time.perf_counter() - t0, 4)}
        return _gen()
    METERS[label] = {"records": 1,
                     "seconds": round(time.perf_counter() - t0, 4)}
    return stream


@Pipe
def tee(stream, *, sink_fn):
    """Fan-out: copy every item to sink_fn, main flow undisturbed."""
    for item in stream:
        sink_fn(item)
        yield item


@Pipe
def run_state_and_aggregate(event_stream):
    """Advance state machines, build the report Tree."""
    report = Tree()
    user_states = defaultdict(StandardTier)
    for event in event_stream:
        user = event.user
        state = user_states[user] = next_loyalty_state(user_states[user], event)
        if isinstance(event, PurchaseEvent):
            cat_node = report["users"][user]["categories"]
            cat_node[event.category] = cat_node.get(event.category, 0.0) + event.amount
        report["users"][user]["tier"] = type(state).__name__
        report["users"][user]["total_spent"] = state.spent
    return report


@Pipe
def vip_watch(event_stream):
    """Branch stage: reuse the pure state machine to spot VIP upgrades."""
    states = defaultdict(StandardTier)
    for e in event_stream:
        prev = states[e.user]
        nxt = states[e.user] = next_loyalty_state(prev, e)
        if isinstance(prev, StandardTier) and isinstance(nxt, VIPTier):
            yield {"user": e.user, "spent": nxt.spent}


@Pipe
def export_as(tree_data, *, fmt="json"):
    """Dispatch to the self-registered plugin. fmt is KEYWORD ONLY."""
    return SinkPlugin.render(fmt, tree_data)


# =====================================================================
# 6. EXECUTION
# =====================================================================
if __name__ == "__main__":
    raw_webhooks = [
        {"type": "buy", "user": "  Alice ", "item": {"cat": "Electronics", "price": 300}},
        {"type": "buy", "user": "alice", "item": {"cat": "Books", "price": 250}},
        {"type": "buy", "user": "Bob", "item": {"cat": "Audio", "price": -50}},
        {"type": "buy", "user": "Bob", "item": {"cat": "Audio", "price": 120}},
        {"type": "refund", "user": "Bob"},
        {"type": "buy", "user": "Bob", "item": {"cat": "Gaming", "price": 80}},
        {"type": "ping", "timestamp": 123456789},
    ]

    tapped = []  # the tee branch collects here
    result = (
        raw_webhooks
        | parse_events()
        | meter(label="parse")
        | tee(sink_fn=tapped.append)
        | run_state_and_aggregate()
        | meter(label="aggregate")
        | export_as(fmt="json")
    )

    print("Plan:", result)
    print("\n--- JSON PLUGIN OUTPUT ---")
    print(result.unwrap())

    print("\n--- VIP ALERTS (tee branch) ---")
    print((tapped | vip_watch() | export_as(fmt="alerts")).unwrap())

    print("\n--- QUARANTINE (refused records) ---")
    print(SinkPlugin.render("quarantine", None))

    print("\n--- STAGE METERS ---")
    for label, m in METERS.items():
        print(f"• {label}: {m['records']} records in {m['seconds']}s")

from collections import defaultdict
from dataclasses import dataclass
from functools import partial
from itertools import combinations
import mmap
import struct
import tempfile
import os

class Pipe:
    def __init__(self, func):
        self.func = func
    def __or__(self, other):
        return Pipe(lambda x: other.func(self.func(x)))
    def __ror__(self, other):
        return self.func(other)
    def __call__(self, *args, **kwargs):
        return Pipe(partial(self.func, *args, **kwargs))

EVOLVED_48_MASKS = (
    3, 5, 9, 11, 15, 17, 23, 27, 29, 31, 33, 37, 39, 43, 45, 47,
    49, 51, 53, 57, 59, 63, 65, 67, 71, 73, 77, 79, 81, 83, 85, 87,
    89, 91, 93, 97, 99, 101, 103, 105, 107, 111, 115, 117, 119, 121, 125, 127
)

def h14_transform(m: int) -> int:
    ext = (m & 1) | ((~m & 0b1111110) & 0x7F)
    return m | (ext << 7)

@Pipe
def audit_h14_matrix(masks):
    cols_14 = tuple(h14_transform(m) for m in masks)
    weights = [c.bit_count() for c in cols_14]
    assert all(w == 8 for w in weights), "Weight-8 invariant violated!"
    d1_aliases = sum(
        1 for c1, c2 in combinations(cols_14, 2)
        if (c1 ^ c2).bit_count() < 2
    )
    return {
        "columns": len(cols_14),
        "total_ones": sum(weights),
        "popcount1_aliases": d1_aliases,
        "codec_status": "VERIFIED_ZERO_COLLISION"
    }

@dataclass(slots=True)
class TelemetryRecord:
    user_id: int
    amount: float
    flags: int

RECORD_STRUCT = struct.Struct("<QfI")

@Pipe
def stream_binary_file(file_path):
    with open(file_path, "rb") as f:
        with mmap.mmap(f.fileno(), 0, access=mmap.ACCESS_READ) as mm:
            with memoryview(mm) as mv:
                for (user_id, amount, flags) in RECORD_STRUCT.iter_unpack(mv):
                    yield TelemetryRecord(user_id=user_id, amount=round(amount, 2), flags=flags)

@Pipe
def filter_and_refuse_faults(record_stream):
    refused = 0
    for rec in record_stream:
        if rec.flags == 0 or rec.amount <= 0:
            refused += 1
            continue
        yield rec

@dataclass(slots=True)
class KimberlingPath:
    target_v: int
    terminal_row: int
    found_n: int | None
    steps: int

@Pipe
def solve_kimberling_targets(targets):
    for v in targets:
        if v < 8:
            continue
        i_star = (v + 4) // 3
        rem = (v + 4) % 3
        j_prev = (2 * i_star - 7) + 2 * rem
        i, j = i_star + 1, j_prev
        steps = 1
        while i != j and steps < 250_000:
            i_next = i + 1
            if i_next >= j + 2:
                j = 2 * i_next - 2 * j - 2
            elif i_next <= j <= 2 * i_next - 3:
                j = 2 * j - 2 * i_next + 1
            else:
                break
            i = i_next
            steps += 1
        found_n = i if i == j else None
        yield KimberlingPath(target_v=v, terminal_row=i_star, found_n=found_n, steps=steps)

if __name__ == "__main__":
    print("=== 1. AUDITING H14 PARITY MATRIX ===")
    h14_report = EVOLVED_48_MASKS | audit_h14_matrix()
    print("H14 Matrix Audit Result:", h14_report)

    print("\n=== 2. ZERO-COPY BINARY PARSING & REFUSAL PIPELINE ===")
    with tempfile.NamedTemporaryFile(delete=False) as tmp:
        tmp_path = tmp.name
        valid_chunk = RECORD_STRUCT.pack(101, 150.75, 1)
        invalid_chunk = RECORD_STRUCT.pack(202, 500.00, 0)
        tmp.write((valid_chunk + invalid_chunk) * 25_000)
    try:
        processed_count = sum(1 for _ in tmp_path | stream_binary_file() | filter_and_refuse_faults())
        print(f"Processed {processed_count} valid, {100000-processed_count} refused.")
    finally:
        os.remove(tmp_path)

    print("\n=== 3. KIMBERLING REVERSE-PATH SOLVER ===")
    targets = [68, 106, 150, 447]
    for result in targets | solve_kimberling_targets():
        print(f"Target v={result.target_v:3d} -> Found n={result.found_n} in {result.steps} reverse steps.")

