@dataclass
class VOIStandard:
    bits: float = 0.0


@dataclass
class VOIVIP:
    bits: float
    perks_unlocked: bool = True


VOI_VIP_THRESHOLD = 500.0


def next_voi_state(state, event):
    """Pure (state, event) tuple state machine over information value."""
    match (state, event):
        case (VOIStandard(bits), SignalEvent(bits=b)) if bits + b >= VOI_VIP_THRESHOLD:
            return VOIVIP(bits=bits + b)
        case (VOIStandard(bits), SignalEvent(bits=b)):
            return VOIStandard(bits=bits + b)
        case (VOIVIP(bits), SignalEvent(bits=b)):
            return VOIVIP(bits=bits + b)
        case (_, RetractionEvent()):
            return VOIStandard(bits=0.0)
        case _:
            return state


