class SinkPlugin:
    _registry = {}

    def __init_subclass__(cls, format_name=None, **kwargs):
        super().__init_subclass__(**kwargs)
        if format_name:
            cls._registry[format_name] = cls

    @classmethod
    def render(cls, format_name, tree_data):
        if format_name not in cls._registry:
            raise ValueError(
                f"Unknown plugin '{format_name}'. "
                f"Available: {sorted(cls._registry)}")
        return cls._registry[format_name]().export(tree_data)


class JSONSink(SinkPlugin, format_name="json"):
    def export(self, data):
        return json.dumps(data, indent=2)


class SummarySink(SinkPlugin, format_name="summary"):
    """Lossy executive summary — drops category detail."""

    def export(self, data):
        lines = ["=== EXECUTIVE PIPELINE SUMMARY ==="]
        for user, profile in data["users"].items():
            lines.append(
                f"- {user.upper()} [{profile['tier']}] "
                f"-> Total: ${profile['total_spent']:.2f}")
        return "\n".join(lines)


class OptimalSink(SinkPlugin, format_name="optimal"):
    """Canonical lossless binary format. Handles both report shapes
    (monetary: total_spent/categories; VOI: total_bits/channels).
    magic "PIPE1" | n_users u8 | per user: name_len u8, name, tier u8,
    total f64, n_groups u8 | per group: name_len u8, name, amount f64."""

    TIER_CODE = {"StandardTier": 0, "VIPTier": 1,
                 "VOIStandard": 0, "VOIVIP": 1}

    def export(self, data):
        buf = io.BytesIO()
        users = data["users"]
        buf.write(b"PIPE1")
        buf.write(struct.pack("<B", len(users)))
        for uname, prof in users.items():
            nb = uname.encode()
            buf.write(struct.pack("<B", len(nb)) + nb)
            buf.write(struct.pack("<B", self.TIER_CODE[prof["tier"]]))
            total = prof.get("total_spent", prof.get("total_bits", 0.0))
            buf.write(struct.pack("<d", total))
            groups = prof.get("categories", prof.get("channels", {}))
            buf.write(struct.pack("<B", len(groups)))
            for gname, amt in groups.items():
                gb = gname.encode()
                buf.write(struct.pack("<B", len(gb)) + gb)
                buf.write(struct.pack("<d", amt))
        return buf.getvalue()


class QuarantineSink(SinkPlugin, format_name="quarantine"):
    """Renders the dead-letter branch: every refused record, with reason."""

    def export(self, data):
        lines = ["=== QUARANTINE — REFUSED RECORDS ==="]
        for q in QUARANTINE:
            lines.append(f"- [{q['stage']}] {q['reason']} :: {q['payload']}")
        lines.append(f"Total refused: {len(QUARANTINE)}")
        return "\n".join(lines)


