@Pipe
def parse_events(raw_stream):
    """Destructure messy dicts into typed monetary events; refuse the rest."""
    QUARANTINE.clear()
    for payload in raw_stream:
        match payload:
            case {"type": "buy", "user": u, "item": {"cat": c, "price": p}}:
                try:
                    yield PurchaseEvent(user=u, category=c, amount=p)
                except ValueError as e:
                    _refuse(payload, str(e), "parse_events")
            case {"type": "refund", "user": str(u)}:
                yield RefundEvent(user=u.strip().lower())
            case _:
                _refuse(payload, "unknown schema", "parse_events")


@Pipe
def parse_signals(raw_stream):
    """Destructure raw dicts into typed information signals; refuse rest."""
    QUARANTINE.clear()
    for payload in raw_stream:
        match payload:
            case {"type": "signal", "user": u, "item": {"channel": c, "bits": b}}:
                try:
                    yield SignalEvent(user=u, channel=c, bits=b)
                except ValueError as e:
                    _refuse(payload, str(e), "parse_signals")
            case {"type": "retract", "user": str(u)}:
                yield RetractionEvent(user=u.strip().lower())
            case _:
                _refuse(payload, "unknown schema", "parse_signals")


@Pipe
def meter(stream, label="stage"):
    """Count what passes through; time it. Records into METERS."""
    t0 = time.perf_counter()
    if inspect.isgenerator(stream) or isinstance(stream, Iterator):
        def _gen():
            n = 0
            for item in stream:
                n += 1
                yield item
            METERS[label] = {"records": n,
                             "seconds": round(time.perf_counter() - t0, 4)}
        return _gen()
    METERS[label] = {"records": 1,
                     "seconds": round(time.perf_counter() - t0, 4)}
    return stream


@Pipe
def tee(stream, *, sink_fn):
    """Fan-out: copy every item to sink_fn; main flow undisturbed."""
    for item in stream:
        sink_fn(item)
        yield item


@Pipe
def run_state_and_aggregate(event_stream):
    """Advance each user's monetary state machine; build the report Tree."""
    report = Tree()
    user_states = defaultdict(StandardTier)
    for event in event_stream:
        user = event.user
        state = user_states[user] = next_loyalty_state(user_states[user], event)
        if isinstance(event, PurchaseEvent):
            cat_node = report["users"][user]["categories"]
            cat_node[event.category] = cat_node.get(event.category, 0.0) + event.amount
        report["users"][user]["tier"] = type(state).__name__
        report["users"][user]["total_spent"] = state.spent
    return report


@Pipe
def run_voi_aggregate(signal_stream):
    """Advance each user's information state machine; build the report."""
    report = Tree()
    user_states = defaultdict(VOIStandard)
    for event in signal_stream:
        user = event.user
        state = user_states[user] = next_voi_state(user_states[user], event)
        if isinstance(event, SignalEvent):
            ch = report["users"][user]["channels"]
            ch[event.channel] = ch.get(event.channel, 0.0) + event.bits
        report["users"][user]["tier"] = type(state).__name__
        report["users"][user]["total_bits"] = state.bits
    return report


@Pipe
def vip_watch(event_stream):
    """Branch: spot monetary VIP upgrades."""
    states = defaultdict(StandardTier)
    for e in event_stream:
        prev = states[e.user]
        nxt = states[e.user] = next_loyalty_state(prev, e)
        if isinstance(prev, StandardTier) and isinstance(nxt, VIPTier):
            yield {"user": e.user, "spent": nxt.spent}


@Pipe
def voi_watch(signal_stream):
    """Branch: spot information-VIP crossings."""
    states = defaultdict(VOIStandard)
    for e in signal_stream:
        prev = states[e.user]
        nxt = states[e.user] = next_voi_state(prev, e)
        if isinstance(prev, VOIStandard) and isinstance(nxt, VOIVIP):
            yield {"user": e.user, "spent": nxt.bits}


@Pipe
def export_as(tree_data, *, fmt="json"):
    """Dispatch to the self-registered plugin. fmt is KEYWORD ONLY."""
    return SinkPlugin.render(fmt, tree_data)


