"""PIPELINE COMPLETE — raw data, no labels. 2026-10-17.
Monsters Ink LLC. Pure Python stdlib.

Fix directive (Taylor): "Use the raw data without labels to fix it."
What was stripped:
  - Tier names (Standard/VIP) -> raw cumulative totals + measured
    threshold crossings. A crossing is a number reaching a number,
    not a status.
  - Synthetic personas (Alice/Bob) -> neutral keys (k1, k2).
  - Tier codes in the binary format -> the crossed flag is derivable
    from total >= threshold; not stored.
  - "Upgraded" language -> "cumulative reached T at X" (measurement).

What remains are mechanisms (pipe, meter, refuse-and-record, tee),
raw event data, and counted results. Nothing else.

§1  PIPE ENGINE   composable stages, inspectable plan, meters,
                  refuse-and-record, tee.
§2  LEDGER DOMAIN raw (key, group, amount) events; cumulative totals;
                  retractions reset to 0.0. Threshold is a parameter.
§3  EXPORT        json / summary / optimal (binary) / refused / crossings.
§4  NEWNESS       novel data units / total data units. Field effect:
                  external input, default UNRESOLVED.

Run:  python3 pipeline_complete.py
"""
from collections import defaultdict
from collections.abc import Iterator
from functools import partial
import inspect
import io
import json
import re
import statistics
import struct
import time


# ===========================================================================
# §1. PIPE ENGINE
# ===========================================================================
METERS = {}     # stage label -> {"records": n, "seconds": t}
REFUSED = []    # refused records: {"payload", "reason", "stage", "t"}


class Pipe:
    def __init__(self, func, name=None, steps=()):
        self.func = func
        self.name = name or getattr(func, "__name__", "stage")
        self.steps = steps or (self.name,)

    def __or__(self, other):
        def composed(x):
            return other.func(self.func(x))
        return Pipe(composed, name="composed", steps=self.steps + other.steps)

    def __ror__(self, other):
        return BoundPipe(self.func(other), self.steps)

    def __call__(self, *args, **kwargs):
        tag = ",".join([repr(a) for a in args] +
                       [f"{k}={v!r}" for k, v in kwargs.items()])
        short = tag if len(tag) <= 25 else tag[:24] + "…"
        label = f"{self.name}({short})"
        p = Pipe(partial(self.func, *args, **kwargs), name=label)
        p.steps = self.steps[:-1] + (label,)
        return p

    def __repr__(self):
        return " → ".join(self.steps)


class BoundPipe:
    def __init__(self, value, steps, _bound=False):
        self.value = value
        self.steps = tuple(steps) if _bound else ("input",) + tuple(steps)

    def __or__(self, pipe):
        return BoundPipe(pipe.func(self.value), self.steps + pipe.steps,
                         _bound=True)

    def __repr__(self):
        return " → ".join(self.steps)

    def unwrap(self):
        return self.value


class Validated:
    def __init__(self, *validators):
        self.validators = validators

    def __set_name__(self, owner, name):
        self.name = name

    def __set__(self, instance, value):
        for validate in self.validators:
            value = validate(self.name, value)
        instance.__dict__[self.name] = value


def clean_str(name, val):
    if not isinstance(val, str) or not val.strip():
        raise ValueError(f"'{name}' must be a non-empty string")
    return val.strip().lower()


def positive_num(name, val):
    if not isinstance(val, (int, float)) or val <= 0:
        raise ValueError(f"'{name}' must be > 0 (got {val})")
    return float(val)


def _refuse(payload, reason, stage):
    REFUSED.append({"payload": payload, "reason": reason,
                    "stage": stage, "t": time.time()})


Tree = lambda: defaultdict(Tree)


# ===========================================================================
# §2. LEDGER DOMAIN — raw accumulations, no tier names
# ===========================================================================
class EntryEvent:
    """Raw ledger entry: key, group, amount."""
    key = Validated(clean_str)
    group = Validated(clean_str)
    amount = Validated(positive_num)

    def __init__(self, key, group, amount):
        self.key = key
        self.group = group
        self.amount = amount


class ResetEvent:
    """Accumulation for a key resets to 0.0."""
    def __init__(self, key):
        self.key = clean_str("key", key)


def accumulate(totals, key, amount, threshold):
    """Returns (new_total, crossed). crossed=True on the step where the
    cumulative first reaches or passes threshold. Raw numbers only."""
    new = totals.get(key, 0.0) + amount
    totals[key] = new
    prev = new - amount
    return new, (prev < threshold <= new)


# ===========================================================================
# §3. EXPORT PLUGINS
# ===========================================================================
class SinkPlugin:
    _registry = {}

    def __init_subclass__(cls, format_name=None, **kwargs):
        super().__init_subclass__(**kwargs)
        if format_name:
            cls._registry[format_name] = cls

    @classmethod
    def render(cls, format_name, tree_data):
        if format_name not in cls._registry:
            raise ValueError(
                f"Unknown plugin '{format_name}'. "
                f"Available: {sorted(cls._registry)}")
        return cls._registry[format_name]().export(tree_data)


class JSONSink(SinkPlugin, format_name="json"):
    def export(self, data):
        return json.dumps(data, indent=2)


class SummarySink(SinkPlugin, format_name="summary"):
    def export(self, data):
        lines = ["=== LEDGER SUMMARY ==="]
        for key, rec in data["keys"].items():
            lines.append(f"- {key}: total {rec['total']:.2f} "
                         f"(threshold {rec['threshold']:.0f}, "
                         f"crossed={rec['crossed']})")
        return "\n".join(lines)


class OptimalSink(SinkPlugin, format_name="optimal"):
    """Canonical lossless binary format. Raw numbers only — no tier codes.
    magic "PIPE1" | n_keys u8 | per key: key_len u8, key, total f64,
    threshold f64 | n_groups u8 | per group: name_len u8, name, amount f64."""

    def export(self, data):
        buf = io.BytesIO()
        keys = data["keys"]
        buf.write(b"PIPE1")
        buf.write(struct.pack("<B", len(keys)))
        for kname, rec in keys.items():
            kb = kname.encode()
            buf.write(struct.pack("<B", len(kb)) + kb)
            buf.write(struct.pack("<d", rec["total"]))
            buf.write(struct.pack("<d", rec["threshold"]))
            groups = rec["groups"]
            buf.write(struct.pack("<B", len(groups)))
            for gname, amt in groups.items():
                gb = gname.encode()
                buf.write(struct.pack("<B", len(gb)) + gb)
                buf.write(struct.pack("<d", amt))
        return buf.getvalue()


class RefusedSink(SinkPlugin, format_name="refused"):
    """Every refused record, with reason. Refuse and record."""

    def export(self, data):
        lines = ["=== REFUSED RECORDS ==="]
        for q in REFUSED:
            lines.append(f"- [{q['stage']}] {q['reason']} :: {q['payload']}")
        lines.append(f"Total refused: {len(REFUSED)}")
        return "\n".join(lines)


class CrossingsSink(SinkPlugin, format_name="crossings"):
    """Measured threshold crossings: key, threshold, total at crossing."""

    def export(self, data):
        lines = ["=== THRESHOLD CROSSINGS ==="]
        for c in data:
            lines.append(f"- {c['key']}: cumulative reached "
                         f"{c['threshold']:.0f} at {c['total']:.2f}")
        if len(lines) == 1:
            lines.append("(none)")
        return "\n".join(lines)


# ===========================================================================
# §4. STAGES
# ===========================================================================
@Pipe
def parse_entries(raw_stream, entry_type="entry", amount_field="amount",
                  group_field="group"):
    """Destructure raw dicts into EntryEvent/ResetEvent; refuse the rest."""
    REFUSED.clear()
    for payload in raw_stream:
        match payload:
            case {"type": t, "key": k, "item": item} if t == entry_type:
                try:
                    yield EntryEvent(key=k, group=item[group_field],
                                     amount=item[amount_field])
                except (ValueError, KeyError, TypeError) as e:
                    _refuse(payload, str(e), "parse_entries")
            case {"type": "reset", "key": str(k)}:
                yield ResetEvent(key=k)
            case _:
                _refuse(payload, "unknown schema", "parse_entries")


@Pipe
def meter(stream, label="stage"):
    t0 = time.perf_counter()
    if inspect.isgenerator(stream) or isinstance(stream, Iterator):
        def _gen():
            n = 0
            for item in stream:
                n += 1
                yield item
            METERS[label] = {"records": n,
                             "seconds": round(time.perf_counter() - t0, 4)}
        return _gen()
    METERS[label] = {"records": 1,
                     "seconds": round(time.perf_counter() - t0, 4)}
    return stream


@Pipe
def tee(stream, *, sink_fn):
    for item in stream:
        sink_fn(item)
        yield item


@Pipe
def run_ledger(event_stream, threshold=500.0):
    """Accumulate per-key totals; record threshold crossings as measured."""
    report = Tree()
    totals = {}
    for event in event_stream:
        key = event.key
        if isinstance(event, ResetEvent):
            totals[key] = 0.0
            continue
        new, crossed = accumulate(totals, key, event.amount, threshold)
        g = report["keys"][key]["groups"]
        g[event.group] = g.get(event.group, 0.0) + event.amount
        report["keys"][key]["total"] = new
        report["keys"][key]["threshold"] = threshold
        report["keys"][key]["crossed"] = (
            report["keys"][key].get("crossed", False) or crossed)
    return report


@Pipe
def watch_crossings(event_stream, threshold=500.0):
    """Branch: yield a record on the step a key's cumulative crosses."""
    totals = {}
    for e in event_stream:
        if isinstance(e, ResetEvent):
            totals[e.key] = 0.0
            continue
        new, crossed = accumulate(totals, e.key, e.amount, threshold)
        if crossed:
            yield {"key": e.key, "threshold": threshold, "total": new}


@Pipe
def export_as(tree_data, *, fmt="json"):
    return SinkPlugin.render(fmt, tree_data)


# ===========================================================================
# §5. NEWNESS — novel data units / total data units
# ===========================================================================
STOPWORDS = {"a", "an", "the", "as", "in", "on", "at", "to", "of", "for",
             "and", "but", "or", "how", "what", "when", "which", "this",
             "that", "these", "those", "it", "its", "is", "are", "was",
             "were", "be", "with", "from", "then", "than", "currently",
             "neither", "other", "one", "several", "anything", "where"}

UNRESOLVED = None


def _toks(t):
    return re.findall(r"[a-z0-9]+", t.lower())


def _bigrams(t):
    w = _toks(t)
    return [" ".join(w[i:i + 2]) for i in range(len(w) - 1)]


def _bignums(t):
    return [x.replace(",", "") for x in re.findall(r"\d[\d,]*", t)
            if len(x.replace(",", "")) >= 2]


def novelty_set(text):
    caps = [w for w in re.findall(r"\b[A-Z][a-zA-Z0-9]*\b", text)
            if w.lower() not in STOPWORDS]
    return set(caps) | set(_bignums(text)) | set(_bigrams(text))


def newness(name, texts):
    mine = novelty_set(texts[name])
    others = set().union(*(novelty_set(t) for n2, t in texts.items()
                           if n2 != name))
    novel = sum(1 for x in mine if x not in others)
    return novel / max(1, len(mine))


def score_corpus(texts, field_effect=None):
    names = list(texts)
    N = {n: novelty_set(texts[n]) for n in names}
    out = {}
    for n in names:
        others = set().union(*(N[m] for m in names if m != n))
        novel = sum(1 for x in N[n] if x not in others)
        nw = novel / max(1, len(N[n]))
        out[n] = {"newness": round(nw, 3),
                  "novel_units": novel,
                  "total_units": len(N[n]),
                  "field_effect": (field_effect or {}).get(n, UNRESOLVED)}
    return out


def derive_bar(scores):
    vs = [s["newness"] for s in scores.values()]
    return statistics.mean(vs) + statistics.pstdev(vs)


# ===========================================================================
# §6. DEMO — raw streams, neutral keys
# ===========================================================================
if __name__ == "__main__":
    print("=" * 60)
    print("LEDGER — raw event stream, neutral keys")
    print("=" * 60)
    raw = [
        {"type": "entry", "key": "k1", "item": {"group": "g1", "amount": 300}},
        {"type": "entry", "key": "k1", "item": {"group": "g2", "amount": 250}},
