        {"type": "reset", "key": "k2"},
        {"type": "entry", "key": "k2", "item": {"group": "g3", "amount": 80}},
        {"type": "ping", "timestamp": 123456789},
    ]
    tapped = []
    result = (
        raw
        | parse_entries()
        | meter(label="parse")
        | tee(sink_fn=tapped.append)
        | run_ledger(threshold=500.0)
        | meter(label="aggregate")
        | export_as(fmt="json")
    )
    print("Plan:", result)
    print(result.unwrap())
    js = result.unwrap()
    opt = (
        raw
        | parse_entries()
        | run_ledger(threshold=500.0)
        | export_as(fmt="optimal")
    ).unwrap()
    print(f"\nOPTIMAL: {len(opt)} bytes vs JSON {len(js)} bytes "
          f"({len(opt)/len(js):.1%}), magic={opt[:5]!r}")
    print((tapped | watch_crossings(threshold=500.0)
           | export_as(fmt="crossings")).unwrap())
    print(SinkPlugin.render("refused", None))

    print("\n" + "=" * 60)
    print("NEWNESS")
    print("=" * 60)
    demo_corpus = {
        "s1": ("The reactor hit 450 kelvin at 08:14. Output held 12.4 MW "
               "for six hours. Engineers credit the new boron lattice."),
        "s2": ("The reactor hit 450 kelvin at 08:14. Output held 12.4 MW "
               "for six hours, sources say. Officials declined comment."),
        "s3": ("Seismometers logged a 3.2 tremor near the ridge array. "
               "No damage reported. Crews are inspecting the pylons."),
    }
    scores = score_corpus(demo_corpus)
    bar = derive_bar(scores)
    for n, s in sorted(scores.items(), key=lambda kv: -kv[1]["newness"]):
        print(f"  {n}: {s['newness']:.3f} ({s['novel_units']}/{s['total_units']})")
    print(f"  bar {bar:.3f} -> "
          f"{[n for n, s in scores.items() if s['newness'] >= bar] or '(none)'}")

    print("\n" + "=" * 60)
    print("METERS")
